import{_ as t,o as d,c as a,ag as o}from"./chunks/framework.CrXGS008.js";const u=JSON.parse('{"title":"Ajustes","description":"","frontmatter":{},"headers":[],"relativePath":"es/repair-station-business/settings.md","filePath":"es/repair-station-business/settings.md"}'),r={name:"es/repair-station-business/settings.md"};function c(s,e,n,i,l,p){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="ajustes" tabindex="-1">Ajustes <a class="header-anchor" href="#ajustes" aria-label="Permalink to &quot;Ajustes&quot;">​</a></h1><p>Cada ajuste de la Repair Station Business se edita en <code>/nay</code>, en la página <strong>Repair Station Business</strong> (scope <code>nay_repair_business.config</code>). Los cambios se guardan en la base de datos y se aplican a todos los jugadores a la vez. <code>config.lua</code> contiene valores iniciales opcionales: se aplican hasta que un ajuste se cambia en <code>/nay</code>, y <strong>Restablecer</strong> vuelve a ellos.</p><p>La columna <strong>En /nay</strong> es el nombre que muestra el panel. La clave es el nombre que usan <code>config.lua</code> y la <a href="/es/nay-lib/api">API HTTP</a>.</p><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><table tabindex="0"><thead><tr><th>En /nay</th><th>Clave</th><th>Tipo</th><th>Por defecto</th><th>Descripción</th></tr></thead><tbody><tr><td>Activado</td><td><code>Enabled</code></td><td>sí / no</td><td>sí</td><td>Activa o desactiva las funciones de propiedad. Desactivadas, las estaciones funcionan como simples Repair Stations. Los propietarios aún pueden sacar dinero de la caja o vender su estación.</td></tr><tr><td>Estaciones en venta sin propietario</td><td><code>UnownedMode</code></td><td><code>open</code> o <code>closed</code></td><td><code>open</code></td><td>Abierta: los jugadores todavía pueden reparar allí. Cerrada: la estación rechaza reparaciones hasta que alguien la compre.</td></tr></tbody></table><h2 id="propiedad" tabindex="-1">Propiedad <a class="header-anchor" href="#propiedad" aria-label="Permalink to &quot;Propiedad&quot;">​</a></h2><table tabindex="0"><thead><tr><th>En /nay</th><th>Clave</th><th>Tipo</th><th>Por defecto</th><th>Descripción</th></tr></thead><tbody><tr><td>Estaciones en venta</td><td><code>Purchasable</code></td><td>lista, hasta 64</td><td>ninguna</td><td>Estaciones que los jugadores pueden comprar. Usa el panel de administración para gestionarlas en el juego.</td></tr><tr><td>Estaciones por jugador</td><td><code>MaxStationsPerPlayer</code></td><td>número, de 1 a 16</td><td>1</td><td>Cuántas estaciones puede tener un jugador.</td></tr><tr><td>Cuenta de compra</td><td><code>BuyAccount</code></td><td><code>cash</code> o <code>bank</code></td><td><code>bank</code></td><td>Cuenta de la que se cobra el precio de compra.</td></tr><tr><td>Recompra (%)</td><td><code>SellBackPercent</code></td><td>número, de 0 a 100</td><td>50</td><td>Parte del precio de compra que se devuelve cuando el propietario vende o pierde la estación.</td></tr><tr><td>Límite de inactividad (días)</td><td><code>InactivityDays</code></td><td>número, de 0 a 90</td><td>14</td><td>Un propietario que no abre la tablet durante este tiempo pierde la estación y recibe un reembolso. 0 lo desactiva.</td></tr></tbody></table><h2 id="stock" tabindex="-1">Stock <a class="header-anchor" href="#stock" aria-label="Permalink to &quot;Stock&quot;">​</a></h2><table tabindex="0"><thead><tr><th>En /nay</th><th>Clave</th><th>Tipo</th><th>Por defecto</th><th>Descripción</th></tr></thead><tbody><tr><td>Capacidad del stock</td><td><code>Capacity</code></td><td>número, de 10 a 10000</td><td>100</td><td>Número máximo de piezas que puede contener una estación.</td></tr><tr><td>Piezas para el motor</td><td><code>PartsEngine</code></td><td>número, de 0 a 100</td><td>2</td><td>Piezas que usa un servicio que repara el motor.</td></tr><tr><td>Piezas para la carrocería</td><td><code>PartsBody</code></td><td>número, de 0 a 100</td><td>3</td><td>Piezas que usa un servicio que repara la carrocería.</td></tr><tr><td>Piezas para los neumáticos</td><td><code>PartsTyres</code></td><td>número, de 0 a 100</td><td>1</td><td>Piezas que usa un servicio que repara los neumáticos.</td></tr><tr><td>Modo de reposición</td><td><code>RestockMode</code></td><td><code>purchase</code>, <code>items</code> o <code>both</code></td><td><code>both</code></td><td>Cómo llenan el stock los propietarios.</td></tr><tr><td>Precio por pieza</td><td><code>PartPrice</code></td><td>número, de 0 a 100000</td><td>40</td><td>Se paga desde el banco del propietario al comprar piezas.</td></tr><tr><td>Objeto de piezas</td><td><code>PartItem</code></td><td>texto, de 1 a 64 caracteres</td><td><code>nay_repair_parts</code></td><td>Objeto del inventario que se entrega para reponer.</td></tr><tr><td>Piezas por objeto</td><td><code>PartsPerItem</code></td><td>número, de 1 a 100</td><td>5</td><td>Piezas que añade un objeto al stock.</td></tr><tr><td>Alerta de stock bajo</td><td><code>LowStockThreshold</code></td><td>número, de 0 a 10000</td><td>10</td><td>Se avisa al propietario cuando el stock baja de este número. 0 lo desactiva.</td></tr></tbody></table><h2 id="precios" tabindex="-1">Precios <a class="header-anchor" href="#precios" aria-label="Permalink to &quot;Precios&quot;">​</a></h2><table tabindex="0"><thead><tr><th>En /nay</th><th>Clave</th><th>Tipo</th><th>Por defecto</th><th>Descripción</th></tr></thead><tbody><tr><td>Precio más bajo (%)</td><td><code>MinPricePercent</code></td><td>número, de 10 a 100</td><td>50</td><td>Parte más baja del precio del servicio que puede fijar un propietario.</td></tr><tr><td>Precio más alto (%)</td><td><code>MaxPricePercent</code></td><td>número, de 100 a 500</td><td>200</td><td>Parte más alta del precio del servicio que puede fijar un propietario.</td></tr><tr><td>Impuesto (%)</td><td><code>TaxPercent</code></td><td>número, de 0 a 90</td><td>10</td><td>Parte de cada pago de reparación que no llega a la caja.</td></tr></tbody></table><h2 id="mapa" tabindex="-1">Mapa <a class="header-anchor" href="#mapa" aria-label="Permalink to &quot;Mapa&quot;">​</a></h2><table tabindex="0"><thead><tr><th>En /nay</th><th>Clave</th><th>Tipo</th><th>Por defecto</th><th>Descripción</th></tr></thead><tbody><tr><td>Color del blip de una estación propia</td><td><code>OwnedBlipColor</code></td><td>número, de 0 a 85</td><td>2</td><td>Color del blip de las estaciones que posees, en tu mapa.</td></tr><tr><td>Color del blip de una estación en venta</td><td><code>ForSaleBlipColor</code></td><td>número, de 0 a 85</td><td>5</td><td>Color del blip de las estaciones en venta.</td></tr></tbody></table><p>Entradas de <strong>Estaciones en venta</strong>:</p><table tabindex="0"><thead><tr><th>En /nay</th><th>Clave</th><th>Tipo</th></tr></thead><tbody><tr><td>Identificador de la estación</td><td><code>StationId</code></td><td>8 caracteres (0 a 9, a a f), como en el editor de la Repair Station.</td></tr><tr><td>Precio</td><td><code>Price</code></td><td>número, de 0 a 100000000</td></tr></tbody></table><p>Los porcentajes del propietario (<code>MinPricePercent</code>, <code>MaxPricePercent</code>) se aplican al precio de cada servicio, antes de los descuentos de trabajo. El impuesto (<code>TaxPercent</code>) se descuenta de cada pago de reparación antes de que llegue a la caja.</p>',16)])])}const b=t(r,[["render",c]]);export{u as __pageData,b as default};
